import re
h=load_history()
e2=[r for r in h if r['epoch']==2]
def parse(q):
    out={}
    for m in re.finditer(r'### Choice ([A-E])\n(.*?)(?=### Choice [A-E]\n|## Your answer|\Z)',q,re.S):
        c,t=m.group(1),m.group(2)
        g=lambda pat: (re.search(pat,t).group(1) if re.search(pat,t) else '?')
        out[c]=dict(T=g(r'training_steps: (\d+)'),bs=g(r'batch_size: (\d+)'),type=g(r'Type: ([^\n]+)'),depth=g(r'Depth: (\d+)'),
                    width=g(r'Width: (\d+)'),res=g(r'Residual connections: (\w+)'),ln=g(r'Layer norm per layer: (\[[^\]]*\])'),
                    act=g(r'Activation: (\w+)'),opt=g(r'Optimizer: (\w+)'),lr=g(r'Learning rate: ([\d.e-]+)'),wd=g(r'Weight decay: ([\d.e-]+)'),
                    betas=g(r'Betas: (\[[^\]]*\])'),mom=g(r'Momentum: ([\d.]+)'),dm=g(r'd_model[^\d]*(\d+)'),heads=g(r'heads[^\d]*(\d+)'),
                    layers=g(r'(\d+) (?:transformer|GRU|recurrent)? ?layers'))
    return out
for qid in ['q_58fea8','q_b070ff','q_1e3031','q_783d1b','q_f05f74','q_65d623','q_1a7ca0','q_97db29']:
    r=[x for x in e2 if x['question_id']==qid][0]
