import itertools, collections, numpy as np, math
c = load_corpus()
def loss(ch): return ch['mean_test_mse'] if ch['mean_test_mse'] is not None else ch['mean_test_ce']
def key(ch): return (ch['optimizer'], ch['lr'], ch['momentum'], ch['training_steps'], ch['batch_size'], ch.get('weight_decay'), str(ch.get('betas')))
def nln(ch): return sum(ch['layer_norm']) if ch['layer_norm'] else 0
def delta(ch):
    o=ch['optimizer']; lr=ch['lr']; T=ch['training_steps']; m=ch['momentum'] or 0
    if o in ('Adam','AdamW','RMSprop'): return lr*T
    if o=='Adagrad': return 2*lr*math.sqrt(T)
    if o=='SGD': return lr*T*0.01/(1-m)
res = collections.defaultdict(lambda:[0,0,[]])
for q in c:
    if q['family']!='spiral_classification': continue
    chs=[x for x in q['choices'] if x['model_type']=='mlp' and loss(x) is not None]
    for a,b in itertools.combinations(chs,2):
        if key(a)!=key(b): continue
        for p,r in ((a,b),(b,a)):
            if (not p['residual']) and r['residual'] and nln(p)>nln(r):
                D=delta(p); tag='D<0.03' if D<0.03 else ('0.03-0.5' if D<0.5 else '>=0.5')
                tag=(tag, nln(r)==0)
                res[tag][0]+= loss(p)<loss(r); res[tag][1]+=1; res[tag][2].append(loss(p)/loss(r))
for k,v in sorted(res.items()): print('spiral plain-moreLN vs res-lessLN',k, f"{v[0]}/{v[1]}", "%.3f"%np.median(v[2]))
