        def g(p):
            mm=re.search(p,t); return mm.group(1).strip() if mm else None
        out[m.group(1)]=dict(depth=g(r'Depth: (\d+)'), w=g(r'Width: (\d+)'), res=g(r'Residual connections: (\w+)'), LN=g(r'Layer norm per layer: (\[.*?\])'), act=g(r'Activation: (\w+)'), opt=g(r'Optimizer: (\w+)'), lr=g(r'Learning rate: ([\d.e-]+)'), mom=g(r'Momentum: ([\d.]+)'))
    st=re.search(r'training_steps: (\d+)', q); bs=re.search(r'batch_size: (\d+)', q)
    return out, st.group(1) if st else None
for qid in ['q_27dc71','q_062cad','q_9db60e','q_e8bd6b','q_b5f3f7','q_440fd0','q_941566','q_211c01','q_0a7f2f','q_8616d0','q_9a8ded']:
    r=[x for x in h if x['question_id']==qid][0]
    o,st=parse(r['question'])
    print(qid, r['family'], 'gold',r['answer'],'steps',st)
    for k,v in o.items(): print('  ',k, v['depth'],v['w'],'res' if v['res']=='True' else 'pl', v['LN'], v['act'], v['opt'], v['lr'], v['mom'])
