import itertools, collections, numpy as np, math
c = load_corpus()
def loss(ch): return ch['mean_test_mse'] if ch['mean_test_mse'] is not None else ch['mean_test_ce']
def key(ch): return (ch['optimizer'], ch['lr'], ch['momentum'], ch['training_steps'], ch['batch_size'])
def nln(ch): return sum(ch['layer_norm']) if ch['layer_norm'] else 0
def delta(ch):
    o=ch['optimizer']; lr=ch['lr']; T=ch['training_steps']; m=ch['momentum'] or 0
    if o in ('Adam','AdamW','RMSprop'): return lr*T
    if o=='Adagrad': return 2*lr*math.sqrt(T)
    return lr*T*0.01/(1-m)
res = collections.defaultdict(lambda:[0,0,[]])
for q in c:
    chs=[x for x in q['choices'] if x['model_type']=='mlp' and loss(x) is not None]
    for a,b in itertools.combinations(chs,2):
        if key(a)!=key(b) or a['width']==b['width']: continue
        if nln(a)!=nln(b) or a['residual']!=b['residual']: continue
        w,n = (a,b) if a['width']>b['width'] else (b,a)
        dd = 'wide-shallower' if w['depth']<n['depth'] else ('same-depth' if w['depth']==n['depth'] else 'wide-deeper')
        D=delta(w); Db = 'L' if D<0.01 else ('M' if D<0.1 else 'H')
        tag=(q['family'], dd, Db)
        res[tag][0]+= loss(w)<loss(n); res[tag][1]+=1; res[tag][2].append(loss(w)/loss(n))
for k,v in sorted(res.items()):
    if 'spiral' in k[0] or 'xor' in k[0]:
        print(k, f"wider wins {v[0]}/{v[1]}", "med %.3f"%np.median(v[2]))
tot=collections.defaultdict(lambda:[0,0])
