{"code": "import itertools,collections
def score(r):return r['depth']+sum(r['layer_norm'])+0.25*bool(r['residual'])
for source in ['lab','corpus']:
 out=[]
 groups=collections.defaultdict(list)
 if source=='lab':
  for r in load_lab():
   if r['family']=='spiral_classification' and r['activation'] in ['relu','leaky_relu'] and r['optimizer']['type'] in ['Adam','AdamW'] and r['optimizer']['lr']>=0.001:groups[r['set_id']].append(r)
 else:
  for q in load_corpus():
   if 'spiral' in q['family']:groups[q['question_id']]=q['choices']
 for rows in groups.values():
  for a,b in itertools.combinations(rows,2):
   if source=='lab':
    if a['optimizer']!=b['optimizer'] or a['loss']!=b['loss']:continue
    ma,mb=a['mean'],b['mean']
   else:
    if a['optimizer'] not in ['Adam','AdamW'] or a['lr']<0.001:continue
    if any(a.get(k)!=b.get(k) for k in ['optimizer','lr','weight_decay','betas','momentum','loss','training_steps','batch_size']):continue
    ma,mb=a['mean_test_ce'],b['mean_test_ce']
   if score(a)==score(b):continue
   out.append((score(a)-score(b))*(ma-mb)<0)
 print(source,len(out),sum(out),len(out)-sum(out))"}

