    o=r['optimizer']; lr=o['lr']; T=r['budget']['training_steps']
    fam=r['family']
    if o['type']=='Adagrad': return 2*lr*math.sqrt(T)
    if o['type']=='SGD':
        m=o.get('momentum') or 0
        g=0.03 if ('regression' in fam and m>0) else 0.01
        return lr*T*g/(1-m)
    return lr*T
def kt(ln):
    k=0
    for x in reversed(ln):
