def delta(opt,lr,T,mom=0,fam=''):
    o=opt.lower()
    if o in('adam','adamw','rmsprop'): return lr*T
    if o=='adagrad': return 2*lr*math.sqrt(T)
    if o=='sgd':
        g=0.01
        return lr*T*g/(1-(mom or 0))
    return lr*T
def labD(r):
    o=r['optimizer']; return delta(o['type'],o['lr'],r['budget']['training_steps'],o.get('momentum',0))
sets=collections.defaultdict(list)
for r in lab:
    if r['model_type']=='mlp' and not r.get('excluded'): sets[r['set_id']].append(r)
def pairs_near_frozen(fams, maxD=0.01, same_opt=True):
    res=collections.defaultdict(lambda:[0,0,[]])
    for sid,rs in sets.items():
        if rs[0]['family'] not in fams: continue
        for a,b in itertools.combinations(rs,2):
