            if same_opt and (a['optimizer']['type']!=b['optimizer']['type'] or a['optimizer']['lr']!=b['optimizer']['lr'] or a['budget']['training_steps']!=b['budget']['training_steps']): continue
            # depth
            if a['depth']!=b['depth']:
                sh,dp=(a,b) if a['depth']<b['depth'] else (b,a)
                k=('depth', rs[0]['family'])
                res[k][0 if sh['mean']<dp['mean'] else 1]+=1; res[k][2].append(sh['mean']/dp['mean'])
            if a['n_ln']!=b['n_ln']:
                lo,hi=(a,b) if a['n_ln']<b['n_ln'] else (b,a)
                k=('moreLN', rs[0]['family'])
                res[k][0 if hi['mean']<lo['mean'] else 1]+=1; res[k][2].append(hi['mean']/lo['mean'])
            if a['residual']!=b['residual']:
